const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
const $=s=>document.querySelector(s),clamp=(n,a,b)=>Math.max(a,Math.min(b,n)),rand=(a,b)=>a+Math.random()*(b-a);
let W=0,H=0,dpr=1,last=0,mode='menu',chosen='nova',keys={},mouse={x:innerWidth/2,y:innerHeight/2,down:false},player,enemy,shots=[],particles=[],score=[0,0],round=1,roundTimer=0,elapsed=0,shake=0;
const arena={r:13};
const obstacles=[{x:-5.5,z:-4,w:2.5,d:2.1,h:2.3,c:'#176071'},{x:5.5,z:-4,w:2.5,d:2.1,h:2.3,c:'#643e54'},{x:-5.5,z:4,w:2.5,d:2.1,h:2.3,c:'#493f70'},{x:5.5,z:4,w:2.5,d:2.1,h:2.3,c:'#65533b'},{x:0,z:-7.1,w:3.3,d:1.15,h:1.45,c:'#1a5962'},{x:0,z:7.1,w:3.3,d:1.15,h:1.45,c:'#623e4f'}];
function resize(){dpr=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=Math.floor(W*dpr);canvas.height=Math.floor(H*dpr);canvas.style.width=W+'px';canvas.style.height=H+'px';ctx.setTransform(dpr,0,0,dpr,0,0);document.body.classList.toggle('mobile',W<760||('ontouchstart'in window));}
addEventListener('resize',resize);resize();
function freshHero(side,type){let tank=type==='bulwark';return{x:side===0?-8:8,z:side===0?0:0,hp:tank?145:110,max:tank?145:110,r:0,side,type,angle:side===0?0:Math.PI,shoot:0,dash:0,pulse:0,over:0,ult:0,invuln:0,flash:0,aiWait:0};}
function startGame(){score=[0,0];round=1;initRound();mode='play';$('#menu').style.display='none';$('#hud').style.display='block';last=performance.now();}
function initRound(){player=freshHero(0,chosen);enemy=freshHero(1,chosen==='nova'?'bulwark':'nova');player.x=-8;enemy.x=8;player.z=0;enemy.z=rand(-1,1);shots=[];particles=[];roundTimer=0;updateHUD();}
$('#startBtn').addEventListener('click',startGame);
document.querySelectorAll('.hero-card').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.hero-card').forEach(x=>x.classList.remove('active'));b.classList.add('active');chosen=b.dataset.hero;}));
function project(x,z,y=0){let s=clamp(1-(z-(player?.z||0))*.012,.78,1.22),zoom=Math.min(W/30,H/19);return{x:W*.5+(x-(player?.x||0))*zoom*s,y:H*.53+(z-(player?.z||0))*zoom*.69*s-y*zoom*s,s};}
function roundedPoly(points,fill,stroke,lw=1){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=lw;ctx.stroke();}}
function drawGround(){
 let a=project(-arena.r,-arena.r),b=project(arena.r,-arena.r),c=project(arena.r,arena.r),d=project(-arena.r,arena.r);
 let g=ctx.createLinearGradient(0,a.y,0,d.y);g.addColorStop(0,'#142a3a');g.addColorStop(.55,'#1b2b3a');g.addColorStop(1,'#243444');roundedPoly([a,b,c,d],g,'#4e7a89',2);
 // arena tile seams and luminous center ring
 for(let n=-12;n<=12;n+=2){let p=project(n,-arena.r),q=project(n,arena.r);ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(q.x,q.y);ctx.strokeStyle=n===0?'#64eee322':'#8cb8c009';ctx.lineWidth=1;ctx.stroke();p=project(-arena.r,n);q=project(arena.r,n);ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(q.x,q.y);ctx.strokeStyle='#8cb8c009';ctx.stroke();}
 let ring=[];for(let i=0;i<64;i++){let t=i*Math.PI*2/64;ring.push(project(Math.cos(t)*4.2,Math.sin(t)*4.2,.015));}ctx.beginPath();ring.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();ctx.strokeStyle='#58ecde55';ctx.lineWidth=2;ctx.stroke();
 // edge rails
 for(let z of [-arena.r,arena.r]){let p=project(-arena.r,z,.15),q=project(arena.r,z,.15);ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(q.x,q.y);ctx.strokeStyle='#68f0e2';ctx.lineWidth=3;ctx.shadowColor='#52f1df';ctx.shadowBlur=14;ctx.stroke();ctx.shadowBlur=0;}
 // center glyph
 let m=project(0,0,.03);ctx.save();ctx.translate(m.x,m.y);ctx.rotate(Math.PI/4);ctx.strokeStyle='#6beee133';ctx.lineWidth=1;ctx.strokeRect(-20,-20,40,40);ctx.strokeRect(-12,-12,24,24);ctx.restore();
}
function drawBlock(o){let p=project(o.x,o.z),s=p.s,hw=o.w*16*s,hd=o.d*13*s,hh=o.h*22*s;
 // drop shadow + top/side faces
 ctx.fillStyle='#02081270';ctx.beginPath();ctx.ellipse(p.x+5,p.y+5,hw*1.1,hd*.8,0,0,Math.PI*2);ctx.fill();
 roundedPoly([{x:p.x-hw,y:p.y-hd},{x:p.x,y:p.y-hd*.68},{x:p.x+hw,y:p.y-hd},{x:p.x,y:p.y-hd*1.32}],o.c,'#7bd8d533');
 roundedPoly([{x:p.x-hw,y:p.y-hd},{x:p.x,y:p.y-hd*1.32},{x:p.x,y:p.y-hd*1.32-hh},{x:p.x-hw,y:p.y-hd-hh}],shade(o.c,.78),'#a2e8e41c');
 roundedPoly([{x:p.x,y:p.y-hd*1.32},{x:p.x+hw,y:p.y-hd},{x:p.x+hw,y:p.y-hd-hh},{x:p.x,y:p.y-hd*1.32-hh}],shade(o.c,.54),'#a2e8e41c');
 ctx.beginPath();ctx.moveTo(p.x-hw*.7,p.y-hd*.98-hh*.48);ctx.lineTo(p.x-hw*.16,p.y-hd*1.12-hh*.48);ctx.strokeStyle='#71f4e733';ctx.lineWidth=2;ctx.stroke();
}
function shade(hex,k){let v=parseInt(hex.slice(1),16),r=clamp(((v>>16)&255)*k,0,255),g=clamp(((v>>8)&255)*k,0,255),b=clamp((v&255)*k,0,255);return`rgb(${r|0},${g|0},${b|0})`;}
function drawArena(){drawGround();obstacles.slice().sort((a,b)=>a.z-b.z).forEach(drawBlock);}
// DRAW_PART2

