function drawHero(h){let p=project(h.x,h.z),s=p.s,enemySide=h.side===1,base=enemySide?'#ff756b':'#59eee0',deep=enemySide?'#732f45':'#145566',ang=h.angle;
 ctx.save();ctx.translate(p.x,p.y);ctx.scale(s,s);
 // shadow
 ctx.fillStyle='#02071188';ctx.beginPath();ctx.ellipse(0,5,21,11,0,0,Math.PI*2);ctx.fill();
 if(h.invuln>0){ctx.strokeStyle=base+'99';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(0,-12,25,30,0,0,Math.PI*2);ctx.stroke();}
 ctx.rotate(Math.atan2(Math.sin(ang)*.7,Math.cos(ang)));
 // legs + boots
 roundedPoly([{x:-12,y:0},{x:-5,y:1},{x:-7,y:12},{x:-13,y:12}], '#101c2a','#7994a22a');roundedPoly([{x:4,y:1},{x:12,y:0},{x:14,y:12},{x:7,y:12}], '#101c2a','#7994a22a');
 ctx.fillStyle=base;ctx.globalAlpha=.72;ctx.fillRect(-14,10,9,3);ctx.fillRect(6,10,9,3);ctx.globalAlpha=1;
 // torso, shoulder plates
 roundedPoly([{x:-12,y:-18},{x:-9,y:-27},{x:8,y:-27},{x:13,y:-19},{x:10,y:-5},{x:-10,y:-5}],deep,'#9bfff088',1.2);
 roundedPoly([{x:-15,y:-22},{x:-10,y:-29},{x:-5,y:-25},{x:-7,y:-16},{x:-14,y:-15}],base,'#d7fff277');
 roundedPoly([{x:7,y:-25},{x:13,y:-28},{x:17,y:-20},{x:13,y:-15},{x:7,y:-17}],shade(base,.72),'#d7fff255');
 // reactor core
 ctx.fillStyle='#d7fff2';ctx.shadowColor=base;ctx.shadowBlur=12;ctx.beginPath();ctx.arc(-1,-18,3.3,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;
 // head + visor
 ctx.fillStyle='#263a4b';ctx.beginPath();ctx.arc(0,-32,7.5,0,Math.PI*2);ctx.fill();ctx.fillStyle=base;ctx.fillRect(-5,-33,10,3);ctx.fillStyle='#f0ffff';ctx.globalAlpha=.85;ctx.fillRect(1,-33,3,2);ctx.globalAlpha=1;
 // arm & weapon point forward
 roundedPoly([{x:1,y:-22},{x:8,y:-21},{x:12,y:-16},{x:9,y:-13},{x:3,y:-17}], '#253b4c');
 roundedPoly([{x:5,y:-21},{x:10,y:-21},{x:22,y:-18},{x:22,y:-14},{x:9,y:-15}],enemySide?'#381f32':'#123641','#bafff066');
 ctx.fillStyle=base;ctx.shadowColor=base;ctx.shadowBlur=8;ctx.fillRect(19,-18,6,3);ctx.shadowBlur=0;
 ctx.restore();
 if(h.flash>0){ctx.fillStyle='#fff9';ctx.beginPath();ctx.arc(p.x,p.y-25*s,15*s,0,Math.PI*2);ctx.fill();}
}
function drawShot(b){let p=project(b.x,b.z,.25),q=project(b.x-b.vx*.085,b.z-b.vz*.085,.25);ctx.beginPath();ctx.moveTo(q.x,q.y);ctx.lineTo(p.x,p.y);ctx.strokeStyle=b.side?'#ff826d':'#73fff1';ctx.lineWidth=3*p.s;ctx.shadowColor=ctx.strokeStyle;ctx.shadowBlur=12;ctx.stroke();ctx.shadowBlur=0;ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(p.x,p.y,2.1*p.s,0,Math.PI*2);ctx.fill();}
function burst(x,z,color,count=9){for(let i=0;i<count;i++){let a=rand(0,Math.PI*2),v=rand(1,5);particles.push({x,z,vx:Math.cos(a)*v,vz:Math.sin(a)*v,life:rand(.25,.65),max:.65,color,size:rand(1.3,3.5)});}}
function drawParticles(dt){for(let i=particles.length-1;i>=0;i--){let p=particles[i],q=project(p.x,p.z,.15);ctx.globalAlpha=clamp(p.life/p.max,0,1);ctx.fillStyle=p.color;ctx.shadowColor=p.color;ctx.shadowBlur=10;ctx.beginPath();ctx.arc(q.x,q.y,p.size*q.s,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.globalAlpha=1;}}
function background(){let g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#07111e');g.addColorStop(.58,'#101d2a');g.addColorStop(1,'#0b1722');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
 // distant skyline silhouettes
 for(let i=0;i<18;i++){let x=i*W/17,hh=(.1+((i*37)%11)/50)*H;ctx.fillStyle=i%3?'#101e2b':'#132736';ctx.fillRect(x,H*.33-hh,W/20,hh);ctx.fillStyle='#65ded61a';ctx.fillRect(x+5,H*.33-hh+10,2,hh-15);}
 let glow=ctx.createRadialGradient(W*.5,H*.5,20,W*.5,H*.53,H*.65);glow.addColorStop(0,'#183647');glow.addColorStop(1,'#08131f00');ctx.fillStyle=glow;ctx.fillRect(0,0,W,H);
}
function render(dt){background();drawArena();let actors=[...shots];let people=[player,enemy].filter(Boolean).sort((a,b)=>a.z-b.z);people.forEach(drawHero);shots.forEach(drawShot);drawParticles(dt);
 if(shake>0){shake=Math.max(0,shake-dt*18);} }
function setAim(){let zoom=Math.min(W/30,H/19);let dx=(mouse.x-W*.5)/zoom,dy=(mouse.y-H*.53)/(zoom*.69);player.angle=Math.atan2(dy,dx);}
function dist(a,b){return Math.hypot(a.x-b.x,a.z-b.z);}
function shoot(h,targetX,targetZ){if(h.shoot>0||h.hp<=0)return;h.shoot=h.type==='bulwark'?.38:.23;let dx=targetX-h.x,dz=targetZ-h.z,l=Math.hypot(dx,dz)||1,spread=h.side===0?.025:.045;let a=Math.atan2(dz,dx)+rand(-spread,spread),speed=22;shots.push({x:h.x+Math.cos(a)*.58,z:h.z+Math.sin(a)*.58,vx:Math.cos(a)*speed,vz:Math.sin(a)*speed,life:.95,side:h.side,damage:h.type==='bulwark'?12:9});}
function tryMove(h,dx,dz){let nx=clamp(h.x+dx,-11.6,11.6),nz=clamp(h.z+dz,-10.9,10.9);for(const o of obstacles){let rx=o.w*.5+.52,rz=o.d*.5+.52;if(Math.abs(nx-o.x)<rx&&Math.abs(nz-o.z)<rz){if(Math.abs(nx-o.x)>Math.abs(nz-o.z))nx=h.x;else nz=h.z;}}h.x=nx;h.z=nz;}
// LOOP_AND_INPUT

