-- .mobile-controls
.mobile-controls{display:none;pointer-events:none;position:absolute;inset:0}
.mobile-controls{display:block}

-- .touch-actions
.touch-actions{pointer-events:auto;position:absolute;bottom:30px;right:22px;display:flex;align-items:end;gap:9px}

-- .touch-btn
.touch-btn{width:57px;height:57px;border-radius:50%;border:1px solid #67e9dfaa;background:#0b2638dd;color:white;font-size:10px;font-weight:800;touch-action:none}
.touch-btn.fire{width:76px;height:76px;background:#17404add;color:#8efff1}
.touch-btn.dash{border-color:#ff8c70aa}

-- .ability
.ability{width:45px;height:45px;display:grid;place-items:center;border:1px solid #547083;background:rgba(9,24,37,.84);position:relative;font-size:16px;color:#e8f7ff;clip-path:polygon(7px 0,100% 0,100% calc(100% - 7px),calc(100% - 7px) 100%,0 100%,0 7px)}
.ability small{position:absolute;bottom:3px;right:5px;font-size:8px;color:#94b1c1}
.ability.ready{border-color:#4fe7d7;box-shadow:inset 0 0 15px #25c9c324;color:#75fff0}
.ability .cd{position:absolute;inset:0;background:#07111eaa;display:grid;place-items:center;font-size:12px}

-- .mobile .help
.mobile .help{display:none}

-- .mobile .side
.mobile .side{top:13px;width:32vw}
.mobile .side.left{left:11px}
.mobile .side.right{right:11px}

-- @media

.center-msg{pointer-events:auto;cursor:pointer;position:absolute;left:50%;top:39%;transform:translate(-50%,-50%);text-align:center;text-shadow:0 3px 25px #000;white-space:nowrap;display:none}
.mobile-controls{display:none;pointer-events:none;position:absolute;inset:0}
.stick{pointer-events:auto;position:absolute;bottom:28px;left:25px;width:112px;height:112px;border-radius:50%;border:1px solid #a9eaff55;background:#08182688;touch-action:none}
.touch-actions{pointer-events:auto;position:absolute;bottom:30px;right:22px;display:flex;align-items:end;gap:9px}
.abilities{position:absolute;bottom:24px;left:50%;transform:translateX(-50%);display:flex;gap:8px}
.mobile .abilities{display:none}
.mobile .topbar{top:12px}
.mobile .bottomleft{left:18px;top:76px;bottom:auto}

