content.text:
.topbar { position:absolute;top:20px;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:22px;padding:10px 20px;background:linear-gradient(180deg,rgba(8,19,32,.92),rgba(8,19,32,.72));border:1px solid rgba(147,196,220,.16);clip-path:polygon(10px 0,100% 0,100% calc(100% - 10px),calc(100% - 10px) 100%,0 100%,0 10px);box-shadow:0 12px 40px #0005 }
.side { position:absolute;top:22px;display:flex;gap:12px;align-items:center;width:25vw;max-width:330px }
.side.left { left:24px }
.side.right { right:24px;flex-direction:row-reverse;text-align:right }
.status { position:absolute;top:84px;left:50%;transform:translateX(-50%);font-size:9px;letter-spacing:2px;color:#a8c0cc;text-transform:uppercase }
.bottomleft { position:absolute;left:24px;bottom:22px }
.abilities { position:absolute;bottom:24px;left:50%;transform:translateX(-50%);display:flex;gap:8px }
.center-msg { pointer-events:auto;cursor:pointer;position:absolute;left:50%;top:39%;transform:translate(-50%,-50%);text-align:center;text-shadow:0 3px 25px #000;white-space:nowrap;display:none }
.center-msg h2 { margin:0;font-size:clamp(40px,7vw,86px);font-style:italic;letter-spacing:6px;line-height:.95 }
.center-msg p { font-size:11px;letter-spacing:4px;color:#a7bac5 }
.brand { position:fixed;z-index:4;right:23px;top:20px;font-size:9px;letter-spacing:2px;color:#d4e5ef99 }
.brand b { color:#5ce9dd }
.mobile-controls { display:none;pointer-events:none;position:absolute;inset:0 }
.mobile .mobile-controls { display:block }
.mobile .help { display:none }
.mobile .abilities { display:none }
.mobile .bottomleft { left:18px;top:76px;bottom:auto }
.mobile .topbar { top:12px }
.mobile .side { top:13px;width:32vw }
.mobile .side.left { left:11px }
.mobile .side.right { right:11px }
.mobile .bar { width:22vw }
.mobile .name { font-size:9px }
.mobile .portrait { width:35px;height:35px }
.mobile .status { top:65px }
.mobile .menu-card { margin:0;max-width:470px }
.mobile .menu { background:linear-gradient(90deg,rgba(4,11,20,.94),rgba(4,11,20,.48)) }
.mobile .menu h1 { letter-spacing:-3px }
